CREATE TABLE organizations (id VARCHAR(40) PRIMARY KEY, name VARCHAR(150) NOT NULL, industry VARCHAR(100), plan VARCHAR(30), contact VARCHAR(150), status VARCHAR(40) NOT NULL, created_at VARCHAR(40) NOT NULL);
CREATE TABLE users (id VARCHAR(40) PRIMARY KEY, name VARCHAR(100) NOT NULL, email VARCHAR(150) NOT NULL UNIQUE, password_hash VARCHAR(100) NOT NULL, role VARCHAR(30) NOT NULL, org_id VARCHAR(40), team VARCHAR(80), enabled BOOLEAN NOT NULL DEFAULT TRUE, FOREIGN KEY(org_id) REFERENCES organizations(id));
CREATE TABLE tickets (id VARCHAR(40) PRIMARY KEY, title VARCHAR(200) NOT NULL, description TEXT NOT NULL, org_id VARCHAR(40) NOT NULL, requester_id VARCHAR(40) NOT NULL, category VARCHAR(50) NOT NULL, priority VARCHAR(20) NOT NULL, status VARCHAR(40) NOT NULL, assignee_id VARCHAR(40), created_at VARCHAR(40) NOT NULL, updated_at VARCHAR(40) NOT NULL, due_at VARCHAR(40) NOT NULL, response_due_at VARCHAR(40) NOT NULL, first_response_at VARCHAR(40), resolved_at VARCHAR(40), resolution TEXT, escalated BOOLEAN NOT NULL DEFAULT FALSE, FOREIGN KEY(org_id) REFERENCES organizations(id), FOREIGN KEY(requester_id) REFERENCES users(id), FOREIGN KEY(assignee_id) REFERENCES users(id));
CREATE INDEX idx_tickets_org_status ON tickets(org_id,status);
CREATE INDEX idx_tickets_due ON tickets(due_at,status);
CREATE TABLE ticket_comments (id VARCHAR(40) PRIMARY KEY, ticket_id VARCHAR(40) NOT NULL, actor_id VARCHAR(40) NOT NULL, body TEXT NOT NULL, internal_note BOOLEAN NOT NULL, created_at VARCHAR(40) NOT NULL, FOREIGN KEY(ticket_id) REFERENCES tickets(id), FOREIGN KEY(actor_id) REFERENCES users(id));
CREATE TABLE ticket_events (id VARCHAR(40) PRIMARY KEY,ticket_id VARCHAR(40) NOT NULL, actor VARCHAR(120) NOT NULL, action VARCHAR(300) NOT NULL, created_at VARCHAR(40) NOT NULL, FOREIGN KEY(ticket_id) REFERENCES tickets(id));
CREATE TABLE sla_policies (priority VARCHAR(20) PRIMARY KEY, response_minutes INT NOT NULL, resolution_hours INT NOT NULL);
CREATE TABLE onboarding (id VARCHAR(40) PRIMARY KEY, org_id VARCHAR(40) NOT NULL UNIQUE, status VARCHAR(40) NOT NULL, reviewer VARCHAR(100), note TEXT, updated_at VARCHAR(40) NOT NULL, FOREIGN KEY(org_id) REFERENCES organizations(id));
CREATE TABLE onboarding_tasks (id VARCHAR(40) PRIMARY KEY, onboarding_id VARCHAR(40) NOT NULL, title VARCHAR(150) NOT NULL, description VARCHAR(300), completed BOOLEAN NOT NULL DEFAULT FALSE, FOREIGN KEY(onboarding_id) REFERENCES onboarding(id));
CREATE TABLE documents (id VARCHAR(40) PRIMARY KEY, org_id VARCHAR(40) NOT NULL, ticket_id VARCHAR(40), name VARCHAR(200) NOT NULL, content_type VARCHAR(150), size_bytes BIGINT NOT NULL, uploaded_by VARCHAR(100), created_at VARCHAR(40) NOT NULL, FOREIGN KEY(org_id) REFERENCES organizations(id), FOREIGN KEY(ticket_id) REFERENCES tickets(id));
CREATE TABLE notifications (id VARCHAR(40) PRIMARY KEY, user_id VARCHAR(40) NOT NULL, title VARCHAR(200) NOT NULL, body VARCHAR(500), resource_id VARCHAR(40), is_read BOOLEAN NOT NULL DEFAULT FALSE, created_at VARCHAR(40) NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id));
CREATE INDEX idx_notifications_user ON notifications(user_id,is_read);
CREATE TABLE knowledge_articles (id VARCHAR(40) PRIMARY KEY,title VARCHAR(200) NOT NULL, category VARCHAR(60) NOT NULL, summary VARCHAR(400), body TEXT NOT NULL, author VARCHAR(100), status VARCHAR(20) NOT NULL, updated_at VARCHAR(40) NOT NULL);
CREATE TABLE audit_events (id VARCHAR(40) PRIMARY KEY, actor VARCHAR(120) NOT NULL, action VARCHAR(200) NOT NULL, resource_id VARCHAR(40), detail VARCHAR(500), created_at VARCHAR(40) NOT NULL);
